UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `npc_vendor` t WHERE t.`entry` = s.`entry` AND t.`item` = s.`item` AND t.`ExtendedCost` = s.`ExtendedCost` AND t.`type` = s.`type`) AND EXISTS (SELECT 1 FROM `creature_template` c WHERE c.`entry` = s.`entry` AND (c.`npcflag` & 128) = 128)
AND EXISTS (SELECT 1 FROM `creature` c WHERE c.`id` = s.`entry` AND (c.`npcflag` IS NULL OR (c.`npcflag` & 128) = 128))
AND NOT EXISTS (SELECT 1 FROM `npc_vendor` v WHERE v.`entry` = s.`entry` AND (v.`slot` = s.`slot` OR (v.`item` = s.`item` AND v.`type` = 1)))
AND NOT EXISTS (SELECT 1 FROM `npc_vendor` v WHERE v.`item` = -s.`entry`)
AND NOT EXISTS (SELECT 1 FROM `npc_vendor` v JOIN `npc_vendor` ref ON ref.`entry` = -v.`item`
                WHERE v.`entry` = s.`entry` AND v.`item` < 0 AND ref.`item` = s.`item` AND ref.`type` = 1) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'npc_vendor' AND r.`k1` = s.`entry` AND r.`k2` = s.`item` AND r.`k3` = s.`ExtendedCost` AND r.`k4` = s.`type`);
