-- quest_offer_reward: observed entries missing from the local world
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`ID` int unsigned NOT NULL, `RewardText` mediumtext NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`ID`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`ID`, `RewardText`, `note`) VALUES
(91723, 'Well done, my friend. Let me try my calibrations again...', 'eg-link@70790'), -- Delicate Instruments
(91725, 'Oh, that''s a relief! It looks like it''s all here. Thank you!', 'eg-link@70862'), -- Stolen Enchanting Supplies
(92742, 'Thank you. Let me see...', 'eg-link@70862'), -- Testing the Wells
(92744, 'I see... these gills appear to be healthy, for now. But we must not be complacent.', 'eg-link@70862'), -- Murloc Gills
(92909, 'Thanks a bunch! I''ll get to work on an escape plan. In the meantime, take this!', 'eg-link@70862'), -- Harvesting the Harvesters
(96391, 'Judging by this map, it certainly looks like these Dark Irons are planning some sort of incursion into the vaults beneath Ironforge. The band ye busted up to the east must be a scouting force.\r\n\r\nThank ye for bringing me this. If we hurry, we might be able to beat them to whatever their goal is down there.', 'eg-link@70862'), -- Underground Map
(96393, 'A Dark Iron incursion--right beneath our feet? Well, I''m relieved to hear that the Dark Iron commander has been dispatched.\r\n\r\nThe guards will head in and clean up the rest of the rabble. We''ll see to it that the breaches are sealed and the lower levels reinforced to ensure that no further incursions are possible.\r\n\r\nThank ye for yer service to Ironforge, $c. Take this as a small token of my gratitude. Oh, and if ye see that old Wildhammer rockhugger Farsen again, tell ''em to pay me a proper visit.', 'eg-link@70862'), -- Old Ironforge Incursion
(97250, 'So the rumors were true! I expected as much, tensions have been rising along the eastern coast for some time. I knew it would only be a matter of time before conflict crept into our territory.\r\n\r\nHowever, I am skeptical that we played a role in the tavern''s destruction. Too many Horde civilians rely on that route for trade and travel. Perhaps you could investigate further if you find the time.\r\n\r\nIn any case, today''s deed is a victory for the Horde, and a stern warning to the Alliance!', 'eg-link@70862'), -- Wrongly Blamed, Justly Corrected
(97924, 'There you have it, you can now craft your very own Camp Chair. Most folk don''t care much for camps being set up in the center of town, so you''ll need to head into the wilderness if you want to test it out.\r\n\r\nOh, and just remember, no camp is complete without a campfire. You''ll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven''t already, you might want to check in with someone who can train you in the culinary arts to learn the basics.', 'eg-link@70790'), -- Camping 101: Skinning
(98407, 'Quite the armful you have.\r\n\r\nWhile this doesn''t solve our problem out here, I can rest comfortably knowing we''ve discouraged them pushing any further. Great work, $N.', 'eg-link@70862'); -- Show of Force
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `quest_offer_reward` t WHERE t.`ID` = s.`ID`) AND EXISTS (SELECT 1 FROM `quest_template` q WHERE q.`ID` = s.`ID`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'quest_offer_reward' AND r.`k1` = s.`ID`);
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`) SELECT `ID`, `RewardText` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `file`, `note`) SELECT 'quest_offer_reward', s.`ID`, '2026_11_10_02_world_everlake_import_slice7.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_02_world_everlake_import_slice7.sql', `note` = s.`note`;
